-- Volcando estructura para tabla gestion_festivos.festivos
CREATE TABLE IF NOT EXISTS `festivos` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `nombre` varchar(255) NOT NULL,
  `fecha` date NOT NULL,
  `anio` int(11) NOT NULL COMMENT 'Año al que pertenece el festivo',
  `tipo` enum('Nacional','Autonómico','Provincial','Local') NOT NULL,
  `comunidad_id` int(11) DEFAULT NULL COMMENT 'FK a comunidades_autonomas (solo para tipo Autonómico)',
  `provincia_id` int(11) DEFAULT NULL COMMENT 'FK a provincias (solo para tipo Provincial)',
  `municipio_id` int(11) DEFAULT NULL COMMENT 'FK a municipios (solo para tipo Local)',
  `activo` tinyint(1) DEFAULT 1 COMMENT '1=Activo, 0=Inactivo',
  `creado_por` int(11) DEFAULT NULL COMMENT 'ID del usuario que creó',
  `creado_en` timestamp NOT NULL DEFAULT current_timestamp(),
  `modificado_por` int(11) DEFAULT NULL COMMENT 'ID del usuario que modificó',
  `modificado_en` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_festivo` (`fecha`,`tipo`,`comunidad_id`,`provincia_id`,`municipio_id`,`anio`),
  KEY `idx_activo` (`activo`),
  KEY `idx_fecha` (`fecha`),
  KEY `idx_anio` (`anio`),
  KEY `idx_tipo` (`tipo`),
  KEY `idx_comunidad_id` (`comunidad_id`),
  KEY `idx_provincia_id` (`provincia_id`),
  KEY `idx_municipio_id` (`municipio_id`),
  KEY `idx_creado_por` (`creado_por`),
  KEY `idx_modificado_por` (`modificado_por`),
  CONSTRAINT `festivos_ibfk_1` FOREIGN KEY (`comunidad_id`) REFERENCES `comunidades_autonomas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `festivos_ibfk_2` FOREIGN KEY (`provincia_id`) REFERENCES `provincias` (`id`) ON DELETE CASCADE,
  CONSTRAINT `festivos_ibfk_3` FOREIGN KEY (`municipio_id`) REFERENCES `municipios` (`id`) ON DELETE CASCADE,
  CONSTRAINT `festivos_ibfk_4` FOREIGN KEY (`creado_por`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL,
  CONSTRAINT `festivos_ibfk_5` FOREIGN KEY (`modificado_por`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL,
  CONSTRAINT `check_tipo_relacion` CHECK (`tipo` = 'Nacional' and `comunidad_id` is null and `provincia_id` is null and `municipio_id` is null or `tipo` = 'Autonómico' and `comunidad_id` is not null and `provincia_id` is null and `municipio_id` is null or `tipo` = 'Provincial' and `comunidad_id` is null and `provincia_id` is not null and `municipio_id` is null or `tipo` = 'Local' and `comunidad_id` is null and `provincia_id` is null and `municipio_id` is not null)
) ENGINE=InnoDB AUTO_INCREMENT=9627 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

